console.log('  Result:', JSON.stringify(res));
console.log('  a:', res.a, '(type:', typeof res.a + ')');
console.log('  arg:', res.arg, '(type:', typeof res.arg + ')');
console.log('  PASS:', res.a === '01' && res.arg === '01' ? 'YES' : 'NO');
console.log();

console.log('Test 2: Multiple aliases with string default');
res = mri(['--a', '01'], { default: { arg: 'hello' }, alias: { arg: ['a', 'x'] } });
console.log('  Result:', JSON.stringify(res));
console.log('  a:', res.a, '(type:', typeof res.a + ')');
console.log('  x:', res.x, '(type:', typeof res.x + ')');
console.log('  PASS:', res.a === '01' && res.x === '01' ? 'YES' : 'NO');
console.log();

console.log('Test 3: Boolean default with alias');
res = mri(['-f', 'true'], { default: { foo: true }, alias: { foo: 'f' } });
console.log('  Result:', JSON.stringify(res));
console.log('  f:', res.f, '(type:', typeof res.f + ')');
console.log('  foo:', res.foo, '(type:', typeof res.foo + ')');
console.log('  PASS:', res.f === true && res.foo === true ? 'YES' : 'NO');
console.log();

console.log('Test 4: Number default with alias');
res = mri(['-n', '42'], { default: { num: 5 }, alias: { num: 'n' } });
console.log('  Result:', JSON.stringify(res));
console.log('  n:', res.n, '(type:', typeof res.n + ')');
console.log('  num:', res.num, '(type:', typeof res.num + ')');
console.log('  PASS:', res.n === 42 && res.num === 42 ? 'YES' : 'NO');
console.log();

console.log('Test 5: Without default (regression check)');
res = mri(['-s', '01'], { string: 's' });
console.log('  Result:', JSON.stringify(res));
console.log('  s:', res.s, '(type:', typeof res.s + ')');
console.log('  PASS:', res.s === '01' ? 'YES' : 'NO');
console.log();

console.log('Test 6: Default with no value provided');
res = mri([], { default: { arg: 'hello' }, alias: { arg: 'a' } });
console.log('  Result:', JSON.stringify(res));
console.log('  a:', res.a, '(type:', typeof res.a + ')');
console.log('  arg:', res.arg, '(type:', typeof res.arg + ')');
console.log('  PASS:', res.a === 'hello' && res.arg === 'hello' ? 'YES' : 'NO');
